-- Hexagram text group 4: compact lazy-loaded records.
return {
  ["地山谦"] = { index="第15卦", name="地山谦", shortName="谦卦", subtitle="内高外低", rating="中中卦",
  xiang="天赐贫人一封金，不争不抢两平分，彼此分得金到手，一切谋望皆遂心。", summary="这个卦是异卦（下艮上坤）相叠，艮为山，坤为地。地面有山，地卑（低）而山高，是为内高外低，比喻功高不自居，名高不自誉，位高不自傲。这就是谦。",
  career="尚未被人器重，但因品德高尚，终会为人发现。自己不必有意表现，尤其不可放弃谦虚的美德，埋头苦干，一定会得到他人的帮助，在事业上大有作为。", business="较为顺利，但不会获暴利，须逐步积累，故应极其小心谨慎，诚心与他人合作，遵守商业道德，通过自已的勤劳努力，取得商业的发展。",
  fame="天资聪明，但因性格不善于表现自己，起初往往被埋没，自己只要不灰心，继续努力钻研业务，保持谦逊好学精神，更大的成功正在未来。", travel="顺利，但应准备充分，途中小心，渐可忽视安全。", marriage="美满的婚姻应由双方共同去努力争取。否则，恋爱不成功，家庭不能和睦。",
  decision="具有内高外低的谦虚美德，善于团结他人，也能得到别人的帮助，事业很顺利，遇到困难，很快可以化险为夷，有惊无险。由于能够认真吸取别人的长处，进步很快，会畅通无阻，但需要特别注意学业、德业和修养。" },
  ["风山渐"] = { index="第53卦", name="风山渐", shortName="渐卦", subtitle="渐进蓄德", rating="上上卦",
  xiang="俊鸟幸得出笼中，脱离灾难显威风，一朝得意福力至，东西南北任意行。", summary="这个卦是异卦（下艮上巽）相叠。艮为山，巽为木。山上有木，逐渐成长，山也随着增高。这是逐渐进步的过程，所以称渐，渐即进，渐渐前进而不急速。",
  career="在经过一个相对静止的时期后，重新开始了事业的新阶段。这时最怕的是急躁冒进，务必循序上进，脚踏实地。同是注意品德修养，以沉着、谦逊的态度对待事业，可无往而不利。", business="正处在稳步向前发展的阶段，定要把握时机，既不可盲目乐观，也不要停步不前，而应采取逐步前进的策略，量力而行。遵守商业道德，以良好的服务，开拓市场。",
  fame="效法树木植根山上，逐渐生长的精神。在品德和学业两个方面，扎扎实实地提高自己。同时，肩负起改善社会风俗的责任。求名应以渐进为宜，切不可争进。", travel="准备充分，从容外出， 一路平安。", marriage="不可操之过急。幸福、美满，夫妻白头和谐。",
  decision="时来运转的时刻已经到来，切莫错过良机。务必小心谨慎，渐进有益有利。以谦和的态度处世，可以得到强有力的支持，会获得重大成功。" },
  ["艮为山"] = { index="第52卦", name="艮为山", shortName="艮卦", subtitle="动静适时", rating="中下卦",
  xiang="财帛常打心头走，可惜眼前难到手，不如意时且忍耐，逢着闲事休开口。", summary="这个卦是同卦（下艮上艮）相叠。艮为山，二山相重，喻静止。它和震卦相反。高潮过后，必然出现低潮，进入事物的相对静止阶段。静止如山，宜止则止，宜行则行。行止即动和静，都不可失机，应恰到好处，动静得宜，适可而止。",
  career="在经过一段发展后，应进行调整，暂时停止行动，总结经验教训。不可因贪名利而妄进。自我克制，自我约束，谨言慎行，不要盲目追求他人。经过休整后，在适当时机到来时，再大显身手。", business="进入停滞不前的状态，切勿盲目冒进，而宜适时停止，进入安静退守，不要受外界干扰，尤其是应该保持内心和理智上的宁静，更不要轻易与他人合作。等待时机，必有光明前途。",
  fame="应保持纯正的目的，静守正道。勿为功名诱惑，秉守忠厚，可得成功。", travel="慎重为好，宜另择佳日。", marriage="重感情，彼此以诚相待，可白头到老。",
  decision="性格沉静、内向，不喜好活动，也不善于交际，为人忠诚老实，讲信义。注意听取他人的建议，明哲保身。机遇不到，不宜积极活动，该止则止，勿抱不切实际的想法。" },
  ["火山旅"] = { index="第56卦", name="火山旅", shortName="旅卦", subtitle="依义顺时", rating="下下卦",
  xiang="飞鸟树上垒窝巢，小人使计举火烧，君占此卦为不吉，一切谋望枉徒劳。", summary="这个卦是异卦（下艮上离）相叠。此卦与丰卦相反，互为“综卦”。山中燃火，烧而不止，火势不停地向前蔓延，如同途中行人，急于赶路。因而称旅卦。",
  career="正处于创业、发展的阶段，各种困难很多。只要能坚持中正的方针，依正道办事，注意调查，处处小心谨慎，并根据情况的变化，采取应变措施，事业可顺利前进。", business="市场行情犹如旅途一样，意想不到的情况，会随时发生。因此，首先应采取慎重的原则，不要冒险。但也不应缩手缩脚，尤其不要猜疑。开发市场之前，应进行充分的调查研究。",
  fame="根据时代的要求，丰富自己的知识和能力，不断提高自己，并且争取得到他人的相助。", travel="很顺利，且经常出行。因此，要时时注意安全。", marriage="双方的不确定因素较多，如确有感情，可顺其发展，再行确定。婚姻美满。",
  decision="人生处于多变状态，一定要眼光远大，树立大志向，不断地充实自己，以诚心实意和谦虚的态度去待人处事，勿计较一时得失，广泛交际朋友。人生旅途十分顺利。" },
  ["雷山小过"] = { index="第62卦", name="雷山小过", shortName="小过卦", subtitle="行动有度", rating="中上卦",
  xiang="行人路过独木桥，心内惶恐眼里瞧，爽利保保过得去，慢行一定不安牢。", summary="这个卦是异卦（下艮上震）相叠。艮为山，震为雷，过山雷鸣，不可不畏惧。阳为大，阴为小，卦外四阴超过中二阳，故称“小过”，小有越过。",
  career="行动宜谨慎小心，切勿冒险，尤其不得钻营。但只要坚持正当的行为，可勇敢向前，努力奋斗，开拓事业。不过，一定要把握尺度，不要好高骛远，以免招致灾祸。随机应变是关键。", business="对市场行情不十分掌握，可先稍试探一下，随即收敛行为。否则会导致危险。不应大规模行动，也不必胆小怕事。稳扎稳打，逐步发展。",
  fame="应遵循中正的原则和循序渐进的道理，求得稳步前进。切勿追求虚名，更不得不顾实际情况攀高位。", travel="慎重考虑和做好充分准备后再外出，否则不利。", marriage="应较长时间的彼此了解，不可仓促行事。",
  decision="行动必须把握分寸，适可而止。盛时应防止办事过火，应即时收敛自己。过度将不足成事，反会招祸。一切行动都要因应变通，不可固执。" },
  ["水山蹇"] = { index="第39卦", name="水山蹇", shortName="蹇卦", subtitle="险阻在前", rating="下下卦",
  xiang="大雨倾地雪满天，路上行人苦又寒，拖泥带水费尽力，事不遂心且耐烦。", summary="这个卦是异卦（下艮上坎）相叠。坎为水，艮为山。山高水深，困难重重，人生险阻，见险而止，明哲保身，可谓智慧。蹇，跋行艰难。",
  career="诸事开头难，坚持下去，会有好的结果。人生不易，首先得求诸自己，修德养性。志高自信，奋勇进取。逢到困难，得求友人相助，行动不可冒险，必以柔克刚，待机候时，量力而行。", business="逐步起业，冒险行事，自寻苦恼。宜加强商业道德，真诚同他人合作，陷入困境时，不得见死不救，而应奋不顾身。联合行动，可活跃于市场竞争之中。",
  fame="循序渐进，加强自身修道。居静观动，待变，俟机而动，能进则进。内心坦然，不可为追逐名利而冒险。与贤能结合，追随高人，必能转危为安。", travel="出门可能有难，利于西南行。如外出遇难，可得救助，转危为安。", marriage="不很顺利，不得急，宜慎重选择。但应有自知之明。",
  decision="艰难不利。但可视为考验。奋进向前，充满信心，切勿自寻苦恼，交结贤人，相互帮助，坚守中正之道，可遇难呈祥，结得善果。" },
  ["天山遁"] = { index="第33卦", name="天山遁", shortName="遁卦", subtitle="遁世救世", rating="下下卦",
  xiang="浓云蔽日不光明，劝君且莫出远行，婚姻求财皆不利，提防口舌到门庭。", summary="这个卦是异卦（下艮上乾）相叠。乾为天，艮为山。天下有山，山高天退。阴长阳消，小人得势，君子退隐，明哲保身，伺机救天下。",
  career="时运不佳，应考虑退隐，勿与不正派的人同流合污。但不是消极逃避，而是为保存实力，总结经验，把握时机，待机而出。切忌贸然行事，造成不必要的损失。同时勿为眼前小利禄所诱惑。", business="市场进入衰落的状况，行情不佳。决不可执意追求，盲目投入，而应沉着冷静，坚持商业道德，远离小人、奸商，保存自己的实力，等待市场行情好转，再图发展。",
  fame="宜暂名哲保身，甘居退隐。全力总结提高，为复出做准备。", travel="不宜积极行动，而应等待时机，创造条件，争取早日而行。", marriage="勿急于解决，更不可妄动强求。时机成熟时，须以纯正的态度去正确对待。",
  decision="处于衰败时期，小人得志。盲目行动必遭不利。虽不必以恶报恶，但更不可同流合污，因小失大，因权宜轻重，韬光养晦，保存实力，断然离去，不可犹豫不决。潜心发展个人实力，隐忍待机。只要能坚定正道，坚持中正，必可在时机成熟时复出，成就大业。" },
  ["泽山咸"] = { index="第31卦", name="泽山咸", shortName="咸卦", subtitle="相互感应", rating="中上卦",
  xiang="运去黄金失色，时来棒槌发芽，月令极好无差，且喜心宽意大。", summary="这个卦是异卦（下艮上兑）相叠。艮为山；泽为水。兑柔在上，艮刚在下，水向下渗，柔上而刚下，交相感应。感则成。",
  career="和为贵，和则万事兴，务以诚感人，以诚待人。广泛交往朋友，谦虚礼让。树立大志向，坚持主见，不可盲目随大流。不利时应安居待机，不可妄动强求。", business="有利可图。但应以纯正之心，以诚待人，加强合作。市场若不景气，决不可妄动，不可强求，而应静待发展。虚心听取不同意见。",
  fame="志向应宏大，脚踏实地，虚心请教他人，使人悦而应，帮助、重用自己。切莫自我封闭，更不得冷漠孤僻，以广阔的胸怀发展自身。", travel="虽希望外出，但暂时不宜远行。待时机成熟时再出行。", marriage="成功的可能性极大。双方很有感情，但动机务要纯正，婚姻方可幸福、永久。",
  decision="吉祥如意。人际关系好，善于交际。以真诚的态度，无私的心去处世，不会有不利的地方。与他人合作应坚持原则。办事不可优柔寡断。不顺利时，应停止行动，总结经验，以图发展。待人诚恳，但不可与玩弄口舌的小人交往，防止受骗。" },
  ["风地观"] = { index="第20卦", name="风地观", shortName="观卦", subtitle="观下瞻上", rating="中上卦",
  xiang="卦遇蓬花旱逢河，生意买卖利息多，婚姻自有人来助，出门永不受折磨。", summary="这个卦是异卦（下坤上巽）相叠，风行地上，喻德教遍施。观卦与临卦互为综卦，交相使用。在上者以道义观天下；在下者以敬仰瞻上，人心顺服归从。",
  career="事业已出现不顺利的迹象，务必谦虚慎重，高瞻远瞩，尤忌短期行为，心胸开阔，注意搞好人际关系，团结他人，不宜轻率行动。必要时不妨投靠德行高的人，以图再度发展。", business="市场形势不稳定，正处于变动，应谨慎小心，随时观察动向，从长计议，做好退却的准备。",
  fame="贵在自知之明，虚心向他人求教，端正处世态度，尤其不可自我满足，更须守中持正，树立远大理想，勿丧失个人追求的目标，勿偏离正道。", travel="有风险，择日而行。", marriage="不顺利，双方应经受住考验，从长计议，会有理想的结果。",
  decision="具有组织能力，适宜担任负责工作，但人生旅途多曲折，必须注意培养自己的预见性和观察力，办事务必公正，实事求是，注意人心动向，关心他人。尤其不可以陷入小人之道和近视行为之中。应有决断精神，不可盲从，必要时可进行策略依附。" },
  ["火地晋"] = { index="第35卦", name="火地晋", shortName="晋卦", subtitle="求进发展", rating="中上卦",
  xiang="锄地锄去苗里草，谁想财帛将人找，一锄锄出银子来，这个运气也算好。", summary="这个卦是异卦（下坤上离）相叠。离为日，为光明；坤为地。太阳高悬，普照大地，大地卑顺，万物生长，光明磊落，柔进上行，喻事业蒸蒸日上。",
  career="顺利。应遵守正道，迎难而上，克敌制胜，因势利导。树立良好的人际关系，深得人心。全力以赴，不得有丝毫犹豫不决，更忌优柔寡断，而应败不馁，勇往直前。注意和衷共济，共同前进。", business="行情好。市场竞争顺利。但也会遇到一些困难，必迎难而上，因势利导，克敌制胜。争取众人支持。前进中的挫折不可免，只要动机纯正，必可转危为安。",
  fame="经刻苦努力与奋斗，已具备开拓事业的基础，却因无人引荐，暂时不得志，决不可因此自暴自弃，须耐心等待时机。同时，更加积极地创造条件。", travel="克服犹豫心理，大胆前进，可无往而不顺。", marriage="吉星高照。会有理想的结果，但决不可自恃条件优越而抱无所谓的态度或过于挑剔。",
  decision="处于不断上升的形势，不会有过大的阻力。但务必争取众人信任，获取人心，再接再厉，只要动机纯正，克服侥幸心理，必有喜从天降。" },
  ["坤为地"] = { index="第2卦", name="坤为地", shortName="坤卦", subtitle="柔顺伸展", rating="上上卦",
  xiang="肥羊失群入山岗，饿虎逢之把口张，适口充肠心欢喜，卦若占之大吉昌。", summary="这个卦是同卦（下坤上坤）相叠，阴性。象征地（与乾卦相反），顺从天。承载万物，伸展无穷无尽。坤卦以雌马为象征，表明地道生育抚养万物，而又依天顺时，性情温顺。它以“先迷后得”证明“坤”顺从“乾”，依随“乾”，才能把握正确方向，遵循正道，获取吉利。",
  career="诸项事业可以成功，得到预想的结果，但开始出师不利，为困境所扰。切莫冒险急进，须小心谨言慎行，尤其不可单枪匹马，独断专行。取得朋友的关心和支持最为重要，在他人的合作下，共同完成事业。因此，应注重内心修养，积蓄养德，效法大地，容忍负重，宽厚大度，以直率、方正、含蓄为原则，不得贪功自傲，持之以恒，谋求事业的成功。", business="机遇不很好，切莫冒险，以稳健为妥，遇到挫折，务必即时总结经验。注意储存货物，待价而沽，处处小心为是。",
  fame="比较顺利，具备基本条件，踏踏实实，埋头苦干，不追求身外之物，即可吉祥。", travel="宜结伴而行。可去陌生的地方。", marriage="阴盛。以柔克刚，女方柔顺，美好姻缘，白头到老。",
  decision="忠厚、温和，待人真诚，热心助人，因此也能得到他人的帮助，可往往因不提防小人而受到伤害，但无大碍。性格灵活，工作方法多样，可以左右逢源，得到赞许。难，消除灾难。" },
  ["雷地豫"] = { index="第16卦", name="雷地豫", shortName="豫卦", subtitle="顺时依势", rating="中中卦",
  xiang="太公插下杏黄旗，收妖为徒归西歧，自此青龙得了位，一旦谋望百事宜。", summary="这个卦是异卦（下坤上震）相叠，坤为地，为顺；震为雷，为动。雷依时出，预示大地回春。因顺而动，和乐之源。此卦与谦卦互为综卦，交互作用。",
  career="十分顺利，事业可以获得成功，但必须符合实际，顺应潮流，且得自己努力奋斗，树立远大目光，尤其不可因事业的顺利而放松谨慎小心的态度，陷于懒散享乐。否则，必将后悔莫及。", business="时运已到，应大胆行动，即使发生挫折，也可以很快化险为夷。应加强同他人的合作，开诚布公，共同开发事业。",
  fame="天资聪颖，如能坚守正直的品德，严格要求自己，努力上进，不因有成绩骄傲满足，停止前进，而是兢兢业业，不惰不怠，必定可以有重大成功。", travel="充分准备，从容出发，会十分顺利和平安。", marriage="十分顺利，一生顺利和吉祥，但万不可掉以轻心，更不可玩弄感情，否则将会出现悲剧。",
  decision="一生顺利，不会出现大的波折，容易比较顺利得到自己应该得到的。但关键在于自己的努力和奋斗，不得耽于安乐，不可玩物丧志。豁达、大度更有利于健康和长寿。一旦遇到意外的灾害，只要时时严格要求自己，坚守纯正，乐不忘忧，居安思危，必可转危为安。" },
  ["山地剥"] = { index="第23卦", name="山地剥", shortName="剥卦", subtitle="顺势而止", rating="中下卦",
  xiang="鹊遇天晚宿林中，不知林内先有鹰，虽然同处心生恶，卦若逢之是非轻。", summary="这个卦是异卦（下坤上艮）相叠。五阴在下，一阳在上，阴盛而阳孤；高山附于地。二者都是剥落象，故为“剥卦”。此卦阴盛阳衰，喻小人得势，君子困顿，事业败坏。",
  career="时运不佳，乃大势所趋，个人只能顺应时势而暂停行动，静观待变，不可冒险，积极创造条件，增强实力，谨慎隐忍，勿与小人同流。时来运转，成就事业，为期不远。", business="已从高峰转入低落，进入不景气时期，需要认真总结经验教训，进行整顿，尤其不可孤注一掷。景气形势一旦到来，可顺势从容再起。",
  fame="成功的可能性不大，不宜执意强求，应继续创造条件，努力提高自己，充实处世的本领，增强实力，待机东山再起。", travel="暂缓为好。可在充分准备之后动身。", marriage="务须慎重考虑，除非有十分般配者，不要随便进行。双方应注意维护家庭的和睦。",
  decision="一生曲折较多，往往隐入不顺利的境况，甚至绝境。但可绝处逢生。只要冷静分析形势，顽强拼搏，一定会彻底改变命运，获得美好的结果，为他人惊羡。关键是不可急于求成，尤其不可冒险。须顺应时势，并防小人陷害。" },
  ["水地比"] = { index="第8卦", name="水地比", shortName="比卦", subtitle="诚信团结", rating="上上卦",
  xiang="顺风行船撒起帆，上天又助一蓬风，不用费力逍遥去，任意而行大亨通。", summary="这个卦是异卦（下坤上坎）相叠，坤为地；坎为水。水附大地，地纳河海，相互依赖，亲密无间。此卦与师卦完全相反，互为综卦。它阐述的是相亲相辅，宽宏无私，精诚团结的道理。",
  career="顺利能够成功，向前发展，可以得到他人的帮助和辅佐，以诚实、信任的态度去做事。待人宽厚、正直，主动热情，向才德高尚的人士学习，听取建议。", business="愿望能够实现，且有较丰厚的利润，但需要与他人密切合作，真诚交往，讲究商业道德，遵守信义，如唯利是图，贪心不足，或自以为是，会导致严重损失。",
  fame="有成功的希望，不仅要靠个人的努力，更为重要的是他人的赏识和栽培。", travel="旅途平安，一路顺风。", marriage="美好姻缘，相亲相爱，彼此忠诚，白头到老。",
  decision="心地善良，待人忠诚、厚道，乐于帮助他人，也能得到回报。工作勤恳，对自己要求严格，可以实现自己的理想，但要多动脑筋，多思考，善于判断是非，尤其要注意选择朋友，一旦结上品行不端的人，会成为自己的祸患。如果与比自己高明的人交朋友，并取得帮助，会终身受益。" },
  ["天地否"] = { index="第12卦", name="天地否", shortName="否卦", subtitle="不交不通", rating="中中卦",
  xiang="虎落陷坑不堪言，进前容易退后难，谋望不遂自己便，疾病口舌事牵连。", summary="这个卦是异卦（下坤上乾）相叠，其结构同泰卦相反，系阳气上升，阴气下降，天地不交，万物不通。它们彼此为“综卦”，表明泰极而否，否极泰来，互为因果。",
  career="陷入逆境，事业处于衰退阶段，多有不顺利。受小人干扰而不得志，爱挫折。应坚持正道，勿与小人合流，团结志同道合者，自保以等待时机。保持自信心，戒慎恐惧，形势定会好转，事业终能成功。", business="遇到强大的竞争对手，处于不利地位。信息不灵造成重大损失。应格外小心谨慎，坚持守势，等待有利时机到来，再发展自己的营销事业。",
  fame="条件还不成熟，再努力一阵子，并得到他人的帮助，理想可以实现。", travel="会遇到不少麻烦和困难，宜推迟或提前行动。", marriage="容易出现节外生枝的事情，甚至发生挫折和变故，双方若都充满信心，好的结果会出现。",
  decision="本人聪慧，精明，勤奋努力，但不注意人际关系，加上小人的排斥，命运或遭厄运。意志坚强，具有奋斗精神，且克服了不足，尽管付出的代价很高，必能成全事业。" },
  ["泽地萃"] = { index="第45卦", name="泽地萃", shortName="萃卦", subtitle="荟萃聚集", rating="中上卦",
  xiang="游鱼戏水被网惊，跳过龙门身化龙，三尺杨柳垂金钱，万朵桃花显你能。", summary="这个卦是异卦相叠（下坤上兑）。坤为地、为顺；兑为泽、为水。泽泛滥淹没大地，人众多相互斗争，危机必四伏，务必顺天任贤，未雨绸缪，柔顺而又和悦，彼此相得益彰，安居乐业。萃，聚集、团结。",
  career="兴旺发达，团结和睦。正在蒸蒸日上，但水多泛滥，人多竞争必然激烈。盛则必衰，切勿骄傲，谨慎小心为好。但也不得犹豫不决，宜勇往直前，开拓新的业务。务以高尚的品德服众。", business="真诚合作，团结互助。鼓励是事业兴旺发达的标志。大胆开拓市场，稳妥前进，有备无患，必可取得不断发展。",
  fame="光靠个人努力，建树不会很大，定要取得他人的帮助，加上个人的条件方可达到理想的境界。", travel="出行虽可能遇到小麻烦，但不要害怕，应以大局为重，积极行动。", marriage="勿急于求成，相亲相爱，美满幸福。",
  decision="善于团结他人共同合作，具有领导才能。但心胸宽阔，眼光务必远大，以诚信、中正为本，不失原则，尤其要严格要求自己，宽容他人，遭到他人反对时，应认真反省自己，得出教训，以这种心境处世为人，终生可平安，事业必通达。" },
}
